def summarize_cart(prices, tax_rate):
    subtotal = sum(prices)
    tax = subtotal * tax_rate
    total = round(subtotal + tax, 2)

    if total >= 100:
        status = 'manager_review'
    else:
        status = 'approved'

    return {
        'item_count': len(prices),
        'subtotal': subtotal,
        'tax': round(tax, 2),
        'total': total,
        'status': status,
    }

print(summarize_cart([19.99, 35.50, 12.00], 0.08))
